#include <print>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> w = {2, 3, 4, 5}, v = {3, 4, 5, 8};
    int W = 7;
    std::vector<int> dp(W + 1, 0);
    for (int i = 0; i < 4; ++i)
        for (int j = W; j >= w[i]; --j)
            dp[j] = std::max(dp[j], dp[j - w[i]] + v[i]);
    std::println("容量 {} 的背包最多装出价值 {}", W, dp[W]);
    std::vector<int> bad(8, 0);
    for (int i = 0; i < 4; ++i)
        for (int j = w[i]; j <= 7; ++j)
            bad[j] = std::max(bad[j], bad[j - w[i]] + v[i]);
    std::println("正着走那一版最后一格 = {}", bad[7]);
    return 0;
}
// 容量 7 正解 11，正着走那版也是 11：这组数据骗不出错，重 3 值 5 容量 6 才错成 10

